-- SMM Analytics: target schema for Azure SQL Database.
-- The MVP reads the same structure from data/*.json; each JSON file maps to one table below.
-- Load mock data afterwards with db/seed.sql (generated by tools/json_to_sql.py).
-- No GO separators, so the script also runs in the Azure Portal Query editor.

IF OBJECT_ID('dbo.vw_PostEngagement', 'V') IS NOT NULL DROP VIEW dbo.vw_PostEngagement;
IF OBJECT_ID('dbo.Posts', 'U') IS NOT NULL DROP TABLE dbo.Posts;
IF OBJECT_ID('dbo.DailyStats', 'U') IS NOT NULL DROP TABLE dbo.DailyStats;
IF OBJECT_ID('dbo.Accounts', 'U') IS NOT NULL DROP TABLE dbo.Accounts;

-- data/accounts.json
CREATE TABLE dbo.Accounts (
    Id        NVARCHAR(10)  NOT NULL CONSTRAINT PK_Accounts PRIMARY KEY,
    Platform  NVARCHAR(30)  NOT NULL,
    Handle    NVARCHAR(100) NOT NULL,
    Name      NVARCHAR(200) NOT NULL,
    Color     CHAR(7)       NOT NULL
);

-- data/daily_stats.json: one row per account per day
CREATE TABLE dbo.DailyStats (
    AccountId     NVARCHAR(10) NOT NULL CONSTRAINT FK_DailyStats_Accounts REFERENCES dbo.Accounts(Id),
    [Date]        DATE         NOT NULL,
    Followers     INT          NOT NULL,
    NewFollowers  INT          NOT NULL,
    Unfollows     INT          NOT NULL,
    Reach         INT          NOT NULL,
    Impressions   INT          NOT NULL,
    Likes         INT          NOT NULL,
    Comments      INT          NOT NULL,
    Shares        INT          NOT NULL,
    Saves         INT          NOT NULL,
    ProfileVisits INT          NOT NULL,
    CONSTRAINT PK_DailyStats PRIMARY KEY (AccountId, [Date])
);

-- data/posts.json
CREATE TABLE dbo.Posts (
    Id                 INT           NOT NULL CONSTRAINT PK_Posts PRIMARY KEY,
    AccountId          NVARCHAR(10)  NOT NULL CONSTRAINT FK_Posts_Accounts REFERENCES dbo.Accounts(Id),
    [Type]             NVARCHAR(30)  NOT NULL,
    Title              NVARCHAR(300) NOT NULL,
    PublishedAt        DATETIME2(0)  NOT NULL,
    FollowersAtPublish INT           NOT NULL,
    Reach              INT           NOT NULL,
    Impressions        INT           NOT NULL,
    Likes              INT           NOT NULL,
    Comments           INT           NOT NULL,
    Shares             INT           NOT NULL,
    Saves              INT           NOT NULL,
    VideoViews         INT           NULL
);
CREATE INDEX IX_Posts_Account_PublishedAt ON dbo.Posts (AccountId, PublishedAt);

-- ER of a post: (likes + comments + shares + saves) / followers × 100, the same formula the dashboard uses.
-- CREATE VIEW must start its own batch, hence EXEC.
EXEC('CREATE VIEW dbo.vw_PostEngagement AS
SELECT p.Id, a.Platform, p.[Type], p.Title, p.PublishedAt, p.Reach, p.Likes, p.Comments, p.Shares, p.Saves,
       CAST(100.0 * (p.Likes + p.Comments + p.Shares + p.Saves) / NULLIF(p.FollowersAtPublish, 0) AS DECIMAL(6, 2)) AS ER
FROM dbo.Posts AS p
JOIN dbo.Accounts AS a ON a.Id = p.AccountId');
